import{_ as a,o as t,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Backing up CephFS - Abhishek Lekshmanan & Roberto Valverde Cameselle, CERN","description":"","frontmatter":{"title":"Backing up CephFS - Abhishek Lekshmanan & Roberto Valverde Cameselle, CERN","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["CephFS备份","Ceph存储解决方案","备份策略","高可用性","分布式存储"],"categories":["存储技术","Ceph"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Backing_up_CephFS_-_Abhishek_Lekshmanan_Roberto_Valverde_Cameselle_CERN.md","filePath":"posts/2025/Backing_up_CephFS_-_Abhishek_Lekshmanan_Roberto_Valverde_Cameselle_CERN.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Backing_up_CephFS_-_Abhishek_Lekshmanan_Roberto_Valverde_Cameselle_CERN.md"};function i(n,e,s,h,d,_){return t(),r("div",null,[...e[0]||(e[0]=[l('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><h3 id="会议背景与目标" tabindex="-1">会议背景与目标 <a class="header-anchor" href="#会议背景与目标" aria-label="Permalink to &quot;会议背景与目标&quot;">​</a></h3><p>本次会议旨在讨论CERN SE团队在使用Ceph进行备份时遇到的问题，并分享各自的经验与解决方案。会议鼓励参与者分享他们在备份过程中遇到的挑战，特别是与Ceph文件系统（CephFS）相关的备份问题。</p><h3 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h3><h4 id="备份工具与策略" tabindex="-1">备份工具与策略 <a class="header-anchor" href="#备份工具与策略" aria-label="Permalink to &quot;备份工具与策略&quot;">​</a></h4><ul><li><strong>使用的工具</strong>：CERN SE团队主要使用<code>restic</code>工具进行备份，但面临性能问题，尤其是无法使用快照（snapshots）进行备份，因为快照会对性能产生负面影响。</li><li><strong>备份策略</strong>：目前仅对特定的用户请求进行备份，而非全量备份。备份任务被分割为多个小任务，并通过自定义的编排工具进行管理。</li><li><strong>挑战</strong>：由于备份是实时的，无法保证备份的一致性，尤其是在备份过程中文件系统正在被写入时。<code>restic</code>在处理大量小文件时性能较差，导致MDS（元数据服务器）的性能下降。</li></ul><h4 id="快照与性能问题" tabindex="-1">快照与性能问题 <a class="header-anchor" href="#快照与性能问题" aria-label="Permalink to &quot;快照与性能问题&quot;">​</a></h4><ul><li><strong>快照的使用</strong>：部分团队尝试使用快照进行备份，但由于性能问题（尤其是在旧版本如Pacific版本中），许多团队放弃了快照备份。</li><li><strong>最新版本的改进</strong>：CERN SE团队计划在即将发布的Quincy版本中再次尝试使用快照，因为开发者表示已修复了部分性能问题。</li><li><strong>快照的潜在问题</strong>：即使创建和删除快照，系统性能可能不会完全恢复到之前的状态，尤其是在根目录下创建快照时。</li></ul><h4 id="备份目标与频率" tabindex="-1">备份目标与频率 <a class="header-anchor" href="#备份目标与频率" aria-label="Permalink to &quot;备份目标与频率&quot;">​</a></h4><ul><li><strong>备份目标</strong>：部分团队使用S3作为备份目标，但也有团队使用TSM、ZFS等其他存储系统。</li><li><strong>备份频率</strong>：大多数团队选择每日备份，但也有团队根据数据量和重要性选择每周或每两周备份。</li><li><strong>增量备份</strong>：部分团队使用<code>rsync</code>和硬链接的方式进行增量备份，但同样面临处理大量小文件时的性能问题。</li></ul><h4 id="备份对生产系统的影响" tabindex="-1">备份对生产系统的影响 <a class="header-anchor" href="#备份对生产系统的影响" aria-label="Permalink to &quot;备份对生产系统的影响&quot;">​</a></h4><ul><li><strong>性能影响</strong>：备份任务会占用大量I/O资源，导致MDS的缓存被频繁刷新，进而影响生产系统的性能。</li><li><strong>备份调度</strong>：大多数团队选择在夜间或低峰期进行备份，以减少对生产系统的影响。</li></ul><h4 id="备份一致性与恢复" tabindex="-1">备份一致性与恢复 <a class="header-anchor" href="#备份一致性与恢复" aria-label="Permalink to &quot;备份一致性与恢复&quot;">​</a></h4><ul><li><strong>一致性问题</strong>：由于备份是实时的，无法保证备份的一致性，尤其是在备份过程中文件系统正在被写入时。</li><li><strong>恢复测试</strong>：部分团队强调恢复测试的重要性，尤其是对于关键数据，建议定期进行恢复测试以确保备份的可用性。</li></ul><h4 id="未来改进方向" tabindex="-1">未来改进方向 <a class="header-anchor" href="#未来改进方向" aria-label="Permalink to &quot;未来改进方向&quot;">​</a></h4><ul><li><strong>快照的进一步优化</strong>：开发者表示Quincy版本中已修复了部分快照性能问题，建议用户在最新版本中尝试使用快照备份。</li><li><strong>递归M时间（recursive M time）优化</strong>：部分团队提出使用CephFS的递归M时间来优化备份过程，减少对文件系统的遍历，从而提高备份效率。</li><li><strong>通知机制</strong>：有参与者建议引入文件系统通知机制（如inotify），以便在文件发生变化时自动触发备份，减少对文件系统的遍历。</li></ul><h3 id="决定事项与后续行动计划" tabindex="-1">决定事项与后续行动计划 <a class="header-anchor" href="#决定事项与后续行动计划" aria-label="Permalink to &quot;决定事项与后续行动计划&quot;">​</a></h3><ul><li><strong>尝试使用Quincy版本的快照功能</strong>：CERN SE团队计划在Quincy版本中再次尝试使用快照备份，并测试其性能。</li><li><strong>优化备份工具</strong>：继续探索使用递归M时间和其他优化技术来提高备份效率，减少对生产系统的影响。</li><li><strong>恢复测试</strong>：各团队应定期进行恢复测试，确保备份的可用性，并根据测试结果调整备份策略。</li><li><strong>反馈与改进</strong>：各团队应将使用快照和其他备份工具时遇到的问题反馈给Ceph社区，以便开发者进一步优化相关功能。</li></ul>',18)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
